PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate WHERE {
  ?film a dbo:Film ;
        rdfs:label ?filmLabel ;
        dbo:director ?director .
  FILTER (langMatches(lang(?filmLabel), "EN") && (
    CONTAINS(LCASE(STR(?filmLabel)), "devil at 4 o'clock") ||
    CONTAINS(LCASE(STR(?filmLabel)), "encounters in the deep")
  ))
  OPTIONAL { ?director dbo:deathDate ?deathDate. }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "EN")) }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
